// ── Product interface ─────────────────────────────────────────────
class Exporter {
  export(document) { throw new Error('export() not implemented'); }
  get mimeType()   { throw new Error('mimeType not implemented'); }
  get extension()  { throw new Error('extension not implemented'); }
}

// ── Concrete Products ─────────────────────────────────────────────
class PdfExporter extends Exporter {
  get mimeType()  { return 'application/pdf'; }
  get extension() { return '.pdf'; }
  export(document) {
    // Real PDF generation would call pdfkit, puppeteer, etc.
    console.log(`[PDF] Exporting "${document.title}" as PDF...`);
    return { mime: this.mimeType, ext: this.extension, bytes: document.content.length * 2 };
  }
}

class HtmlExporter extends Exporter {
  get mimeType()  { return 'text/html'; }
  get extension() { return '.html'; }
  export(document) {
    console.log(`[HTML] Exporting "${document.title}" as HTML...`);
    const html = `<html><body><h1>${document.title}</h1><p>${document.content}</p></body></html>`;
    return { mime: this.mimeType, ext: this.extension, bytes: html.length };
  }
}

class MarkdownExporter extends Exporter {
  get mimeType()  { return 'text/markdown'; }
  get extension() { return '.md'; }
  export(document) {
    console.log(`[MD] Exporting "${document.title}" as Markdown...`);
    const md = `# ${document.title}\n\n${document.content}`;
    return { mime: this.mimeType, ext: this.extension, bytes: md.length };
  }
}

// ── Creator (abstract) ────────────────────────────────────────────
class DocumentConverter {
  // Factory method — subclasses decide which Exporter to use
  createExporter() { throw new Error('createExporter() not implemented'); }

  // Business logic — implemented entirely via Product interface
  convert(document) {
    const exporter = this.createExporter();
    console.log(`Converting via ${exporter.mimeType}...`);
    const result = exporter.export(document);
    return {
      filename: document.title.replace(/\s+/g, '-') + exporter.extension,
      ...result,
    };
  }

  // Batch conversion — same factory method, same decoupling
  batchConvert(documents) {
    return documents.map(doc => this.convert(doc));
  }
}

// ── Concrete Creators ─────────────────────────────────────────────
class PdfConverter extends DocumentConverter {
  createExporter() { return new PdfExporter(); }
}

class HtmlConverter extends DocumentConverter {
  createExporter() { return new HtmlExporter(); }
}

class MarkdownConverter extends DocumentConverter {
  createExporter() { return new MarkdownExporter(); }
}

// ── Client code — depends ONLY on DocumentConverter interface ─────
function processDocuments(converter, docs) {
  console.log('--- Batch conversion ---');
  const results = converter.batchConvert(docs);
  results.forEach(r => console.log(`  ${r.filename} (${r.bytes} bytes)`));
  return results;
}

const docs = [
  { title: 'Annual Report', content: 'Revenue grew 30% year-over-year...' },
  { title: 'Technical Spec', content: 'The system shall support 10k RPS...' },
];

// Swap the converter → behaviour changes, client code is untouched
processDocuments(new PdfConverter(), docs);
processDocuments(new HtmlConverter(), docs);
processDocuments(new MarkdownConverter(), docs);

// Adding EPUB support: create EpubExporter + EpubConverter — zero edits above
// class EpubExporter extends Exporter { ... }
// class EpubConverter extends DocumentConverter {
//   createExporter() { return new EpubExporter(); }
// }

